function cancelEditShippingfee(ele) {
    $(this).parent().parent().remove();
    $('.edit-shipping-fee-form').removeClass('active');
}
function formatMoney(m) {
    return parseFloat(m).toLocaleString('en-US', {
        maximumFractionDigits: 0
    });
}
function confirmShipping(ele) {
    if ($('.btn-export-booking').length) {
        var bookingid = $(ele).data('bookingid');
        var access_token = $('.access_token').html();
        var shippingfee  = $('.edit-shipping-fee-form.active').find('input[name="shippingfee"]').val();
        if (shippingfee == '') {
            $('.edit-shipping-fee-form.active').find('input[name="shippingfee"]').focus();
            return;
        }
        var shippingdate  = $('.edit-shipping-fee-form.active').find('input[name="shippingdate"]').val();
        if (shippingdate == '') {
            $('.edit-shipping-fee-form.active').find('input[name="shippingdate"]').focus();
            return;
        }
        var requestOrder = {};
        requestOrder.status = 'SHIPPING';
        requestOrder.shippingfee = shippingfee;
        requestOrder.shippingdate = shippingdate;
        $.ajax({
            url: '/api/v0/supplier/'+bookingid+'/update-fees.json',
            type: 'POST',
            data: JSON.stringify(requestOrder),
            dataType: "json",
            contentType: "application/json",
            beforeSend: function(xhr) {
                xhr.setRequestHeader("Authorization", "Bearer " + access_token);
            },
            success: function(result){
                if (result.errorMessage == null) {
                    $('.edit-shipping-fee-form').removeClass('active');
                    var tdstatus = '<div class="status {status}"><span>{status}</span></div>';
                    tdstatus = tdstatus.replace(/\{status\}/g,result.status);
                    $('.tr-booking-id-'+bookingid).find('.td-status').html(tdstatus);
                    var sfee = formatMoney(result.shippingfee);
                    $('.tr-booking-id-'+bookingid).find('.td-shipping-fee').html(sfee);
                    $('.tr-booking-id-'+bookingid).find('.td-shipping-date').html(shippingdate);
                    var finalamount = formatMoney(result.finalamount);
                    $('.tr-booking-id-'+bookingid).find('.finalamount').html(finalamount);
                } else {
                    alert(result.errorMessage);
                }
            },
            error: function (e){
                console.log('...................', e)
            }
        });
    }
}
function openStatusModal(bookingid) {
    var access_token = $('.access_token').html();
    $.ajax({
        url: '/api/v0/supplier/'+bookingid+'/mybooking.json',
        type: 'GET',
        contentType: "application/json",
        beforeSend: function(xhr) {
            xhr.setRequestHeader("Authorization", "Bearer " + access_token);
        },
        success: function(result){
            $('#statusModal .current-status').html(result.status);
            $('#statusModal .bookingid').val(bookingid);
            var lis = '<li class="list-group-item">'+result.bookerName +'</li>';
            lis += '<li class="list-group-item">'+result.address + ' / ' + result.bookerPhone +'</li>';
            for (var i=0;i<result.products.length;i++) {
                var item = result.products[i];
                lis += '<li class="list-group-item">'+ item.productname + ': ' + item.price + ' x ' + item.quantity +'</li>';
            }
            $('#statusModal .list-group').html(lis);
            if (result.status != 'DONE' && result.status != 'CANCELLED' && result.status != 'RETURNED') {
                $('.btn-returned').removeClass('d-none');
                $('.btn-cancelled').removeClass('d-none');
                $('.btn-done').removeClass('d-none');
            } else {
                $('.btn-returned').addClass('d-none');
                $('.btn-cancelled').addClass('d-none');
                $('.btn-done').addClass('d-none');
            }
        },
        error: function (e){
            console.log('...................', e)
        }
    });
    $('#statusModal').modal('show');
}
function saveStatus(status) {
    $('#statusModal').modal('hide');
    var access_token = $('.access_token').html();
    var bookingid = $('#statusModal .bookingid').val();
    if (bookingid != '') {
        $.ajax({
            url: '/api/v0/supplier/'+bookingid+'/' + status +'/update-status.json',
            type: 'POST',
            contentType: "application/json",
            beforeSend: function(xhr) {
                xhr.setRequestHeader("Authorization", "Bearer " + access_token);
            },
            success: function(result){
                var tdstatus = '<div class="status {status}"><span>{status}</span></div>';
                tdstatus = tdstatus.replace(/\{status\}/g,status);
                $('.tr-booking-id-'+bookingid).find('.td-status').html(tdstatus);
                $('#statusModal .current-status').html('');
                $('#statusModal .bookingid').val('');
                $('#statusModal .list-group').html('');
            },
            error: function (e){
                console.log('...................', e)
            }
        });
    }
}
function gotoPage(page) {
    $("#formPage").val(page);
    $("#myBookingForm").submit();
}
$(document).ready(function() {
    $('.datepicker').flatpickr({
        enableTime: false,
        dateFormat: "d/m/Y",
    });
    if ($('.btn-export-booking').length) {
        $('.btn-export-booking').click(function (e) {
            window.location = '/my/booking/export?' + $("#myBookingForm").serialize();
        });
        var editTemp = $('#edit-shipping-fee-template').html();
        $('.edit-shipping-fee.REQUEST').click(function (e) {
            $('.edit-shipping-fee-form').removeClass('active');
            $(this).parent().find('.edit-shipping-fee-form').addClass('active');
            var bookingid = $(this).data('bookingid');
            var access_token = $('.access_token').html();
            $.ajax({
                url: '/api/v0/supplier/'+bookingid+'/mybooking.json',
                type: 'GET',
                contentType: "application/json",
                beforeSend: function(xhr) {
                    xhr.setRequestHeader("Authorization", "Bearer " + access_token);
                },
                success: function(result){
                    if (result.status == 'REQUEST') {
                        var content = editTemp.replace(/\{bookingid\}/g,bookingid).replace('{shippingfee}',result.shippingfee);
                        var lis = '';
                        for (var i=0;i<result.products.length;i++) {
                            var item = result.products[i];
                            lis += '<li class="list-group-item">'+item.productname+ ' x ' + item.quantity +'</li>';
                        }
                        content = content.replace('{lis}',lis).replace('{city}',result.city);
                        $('.edit-shipping-fee-form.active').html(content);
                        $('.edit-shipping-fee-form.active .shipping-datetime').flatpickr({
                            enableTime: true,
                            dateFormat: "d/m/Y H:i",
                            minTime: "06:00",
                            maxTime: "22:00"
                        });
                    } else {
                        $('.edit-shipping-fee-form').removeClass('active');
                    }
                },
                error: function (e){
                    $('.edit-shipping-fee-form').removeClass('active');
                    console.log('...................', e)
                }
            });
        });
    }
    $('.bd-sidebar').find('.bd-sidebar-booking').addClass('active');
    function changeCity() {
        $('.cus-zip').find('option').not(':first').remove();
        var citycode = $('.cus-city').val();
        var countryid = $('.d-none.countryid').html();
        $.ajax({
            url: '/ajax/findWardsByCity.html?countryid='+countryid+'&citycode='+citycode,
            type: 'GET',
            contentType: "application/json",
            success: function(result) {
                if (result.array.length > 0) {
                    var wardArray = result.array;
                    for (var i=0;i<wardArray.length;i++) {
                        var $option = '<option value="'+wardArray[i].zip+'">'+wardArray[i].name+'</option>';
                        $('.cus-zip').append($option);
                    }
                }
            }
        });
    }
    $('.cus-city').on('change',function(){
        changeCity();
    });
    function changeState() {
        $('.cus-city').find('option').not(':first').remove();
        var statecode = $('.cus-state').val();
        if (statecode != '') {
            var countryid = $('.d-none.countryid').html();
            $.ajax({
                url: '/ajax/findCitiesByCountry.html?countryid='+countryid+'&statecode='+statecode,
                type: 'GET',
                contentType: "application/json",
                success: function(result) {
                    if (result.array.length > 0) {
                        var ctArray = result.array;
                        for (var i=0;i<ctArray.length;i++) {
                            var $option = '<option value="'+ctArray[i].code+'">'+ctArray[i].name+'</option>';
                            $('.cus-city').append($option);
                        }
                    }
                }
            });
        }
    }
    $('.cus-state').on('change',function(){
        changeState();
    });
    $('.change-status').on('click',function(){
        if ($('#statusModal').length) {
            var bookingid = $(this).data('bookingid');
            openStatusModal(bookingid);
        }
    });
});